// DASHBOARD — full notification system (bell, alert centre, live pop-ups, toasts, PWA, branded push)
import { writeFileSync, mkdirSync, existsSync } from "fs";
import { dirname } from "path";
if (!existsSync("src/app/(app)/layout.js")) {
  console.error("\n  Galat folder! Pehle sahi folder mein jao (jahan src/app/(app)/layout.js hai), phir dobara chalao.\n");
  process.exit(1);
}
const files = {
 "public/sw.js": "",
 "public/icon-192.png": "",
 "public/icon-512.png": "",
 "public/badge-96.png": "",
 "src/app/apple-icon.png": "",
 "src/app/manifest.js": "",
 "src/lib/notify.js": "",
 "src/lib/notification-actions.js": "",
 "src/lib/toast.js": "",
 "src/lib/use-push.js": "",
 "src/components/notif-meta.js": "",
 "src/components/Toaster.js": "",
 "src/components/NotificationBell.js": "",
 "src/components/NotificationSettings.js": "",
 "src/components/BillingToast.js": "",
 "src/app/(app)/notifications/page.js": "",
 "src/app/(app)/layout.js": "",
 "src/app/(app)/billing/page.js": "",
 "src/components/AiFrontDeskForm.js": "",
 "src/components/ServicesManager.js": "",
 "src/components/KnowledgeManager.js": "",
 "src/components/TeamManager.js": "",
 "src/components/CampaignsManager.js": "",
 "src/components/ConnectWhatsApp.js": "",
 "src/lib/whatsapp-actions.js": "",
 "src/app/api/stripe/webhook/route.js": ""
};
for (const [p, b64] of Object.entries(files)) {
  mkdirSync(dirname(p), { recursive: true });
  writeFileSync(p, Buffer.from(b64, "base64"));
  console.log("  wrote " + p);
}
import { execSync } from "child_process";
console.log("\n  Installing web-push ...");
try { execSync("npm install web-push@3.6.7 --save", { stdio: "inherit" }); }
catch (e) { console.error("  npm install fail hua — khud chalao: npm install web-push"); }
console.log("\nDone. Ab: git add . && git commit -m \"Notification system\" && git push");
